def min_path_sum(g):
    R_, C = len(g), len(g[0]); dp = [float("inf")] * C; dp[0] = 0
    for i in range(R_):
        dp[0] += g[i][0]
        for j in range(1, C): dp[j] = g[i][j] + min(dp[j], dp[j - 1])
    return dp[-1]

