int minPathSum(vector<vector<int>>& g) {
    int R = g.size(), C = g[0].size(); vector<int> dp(C, INT_MAX); dp[0] = 0;
    for (int i = 0; i < R; i++) { dp[0] += g[i][0]; for (int j = 1; j < C; j++) dp[j] = g[i][j] + min(dp[j], dp[j - 1]); }
    return dp[C - 1];
}
